// Python-style repr() formatting helpers.
// Used so console.log output matches Python's print() character by character.

export function pyRepr(value) {
  if (value === true) return 'True';
  if (value === false) return 'False';
  if (value === null || value === undefined) return 'None';
  if (typeof value === 'number') return pyReprNumber(value);
  if (typeof value === 'string') return pyReprString(value);
  if (Array.isArray(value)) return pyReprList(value);
  if (value instanceof Map) return pyReprDict(value);
  throw new TypeError(`pyRepr: unsupported value: ${String(value)}`);
}

function pyReprNumber(n) {
  if (Number.isInteger(n)) return String(n);
  // Python float repr: always shows a decimal point for integral floats
  if (Number.isFinite(n) && Math.floor(n) === n) return `${n}.0`;
  return String(n);
}

function pyReprString(s) {
  // Python prefers single quotes unless the string contains one
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else out += ch;
  }
  return out + quote;
}

function pyReprList(arr) {
  return '[' + arr.map(pyRepr).join(', ') + ']';
}

// Python tuple repr: 1-element tuples get a trailing comma
export function pyReprTuple(items) {
  if (items.length === 1) return '(' + pyRepr(items[0]) + ',)';
  return '(' + items.map(pyRepr).join(', ') + ')';
}

function pyReprDict(map) {
  const parts = [];
  for (const [k, v] of map.entries()) {
    parts.push(pyRepr(k) + ': ' + pyRepr(v));
  }
  return '{' + parts.join(', ') + '}';
}

// Reimplementation of the boltons.iterutils interfaces used by the source
// script, based purely on observed behavior (black-box).

// partition(src, pred) -> [truthyList, falsyList]
// Items keep their original relative order within each list.
export function partition(src, pred) {
  const truthy = [];
  const falsy = [];
  for (const item of src) {
    if (pred(item)) truthy.push(item);
    else falsy.push(item);
  }
  return [truthy, falsy];
}

// bucketize(src, keyFn) -> Map preserving first-seen key insertion order,
// matching how Python dicts print their entries.
export function bucketize(src, keyFn) {
  const buckets = new Map();
  for (const item of src) {
    const key = keyFn(item);
    if (!buckets.has(key)) buckets.set(key, []);
    buckets.get(key).push(item);
  }
  return buckets;
}

// Python int() semantics for base-10 string conversion.

export class PyValueError extends Error {
  constructor(literal) {
    super(`invalid literal for int() with base 10: ${pyStrRepr(literal)}`);
    this.name = 'ValueError';
  }
}

function pyStrRepr(s) {
  // enough fidelity for the error message (Python uses repr of the string)
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  const escaped = s
    .replace(/\\/g, '\\\\')
    .replace(new RegExp(quote, 'g'), '\\' + quote)
    .replace(/\n/g, '\\n')
    .replace(/\r/g, '\\r')
    .replace(/\t/g, '\\t');
  return quote + escaped + quote;
}

// int(x): strips surrounding whitespace, accepts optional +/- sign and
// decimal digits only. Anything else raises ValueError.
export function pyInt(x) {
  const trimmed = x.replace(/^\s+|\s+$/g, '');
  if (!/^[+-]?\d+$/.test(trimmed)) {
    throw new PyValueError(x);
  }
  return parseInt(trimmed, 10);
}

// Minimal argparse replica covering exactly what the source script uses:
// one required string option `--a`, plus -h/--help.
// Error/usage/help text and exit codes mirror Python argparse.

import { basename } from 'node:path';

export class ArgumentParser {
  constructor({ prog, helpTexts = {} } = {}) {
    this.prog = prog ?? basename(process.argv[1] ?? 'prog');
    this.helpTexts = helpTexts;
  }

  usage() {
    return `usage: ${this.prog} [-h] --a A`;
  }

  printHelp() {
    console.log(this.usage());
    console.log('');
    console.log('options:');
    console.log('  -h, --help  show this help message and exit');
    console.log(`  --a A       ${this.helpTexts.a ?? ''}`);
  }

  error(message) {
    process.stderr.write(this.usage() + '\n');
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  // Mimics argparse's negative-number heuristic: a token starting with '-'
  // is treated as an option string unless it looks like a negative number.
  looksLikeOption(token) {
    if (!token.startsWith('-') || token === '-') return false;
    return !/^-\d+$|^-\d*\.\d+$/.test(token);
  }

  parseArgs(argv = process.argv.slice(2)) {
    let a;
    const unrecognized = [];

    for (let i = 0; i < argv.length; i++) {
      const token = argv[i];
      if (token === '-h' || token === '--help') {
        this.printHelp();
        process.exit(0);
      } else if (token === '--a') {
        const next = argv[i + 1];
        if (next === undefined || this.looksLikeOption(next)) {
          this.error('argument --a: expected one argument');
        }
        a = next; // repeated options: last one wins
        i++;
      } else if (token.startsWith('--a=')) {
        a = token.slice('--a='.length);
      } else {
        unrecognized.push(token);
      }
    }

    // argparse reports missing required arguments before unrecognized ones
    if (a === undefined) {
      this.error('the following arguments are required: --a');
    }
    if (unrecognized.length > 0) {
      this.error(`unrecognized arguments: ${unrecognized.join(' ')}`);
    }

    return { a };
  }
}

import { ArgumentParser } from './lib/argparse.mjs';
import { partition, bucketize } from './lib/iterutils.mjs';
import { pyInt, PyValueError } from './lib/pyint.mjs';
import { pyRepr, pyReprTuple } from './lib/pyrepr.mjs';

const parser = new ArgumentParser({ helpTexts: { a: 'Comma-separated numbers' } });
const args = parser.parseArgs();

let numbers;
try {
  numbers = args.a.split(',').map(pyInt);
} catch (err) {
  if (err instanceof PyValueError) {
    // Mirror the unhandled-exception behavior of the original script
    process.stderr.write('Traceback (most recent call last):\n');
    process.stderr.write('  File "test7.py", line 8, in <module>\n');
    process.stderr.write(`${err.name}: ${err.message}\n`);
    process.exit(1);
  }
  throw err;
}

const result1 = partition(numbers, (x) => x % 2 === 0); // 分区为偶数和奇数
console.log(pyReprTuple(result1));
const result2 = partition(numbers, (x) => x > 0); // 分区为正数和负数
console.log(pyReprTuple(result2));
const result3 = bucketize(numbers, (x) => x % 2 === 0); // 按奇偶分组
console.log(pyRepr(result3));
const result4 = bucketize(numbers, (x) => x > 10); // 按是否大于10分组
console.log(pyRepr(result4));
